pwsh -NoLogo -NoProfile -Command '
$files = @("./podex.ps1","./api/_lib/pantry-store.ps1")
$ok = $true
foreach ($f in $files) {
	$errs = $null
	[System.Management.Automation.Language.Parser]::ParseFile((Resolve-Path $f), [ref]$null, [ref]$errs) | Out-Null
	if ($errs) { $ok=$false; Write-Host "PARSE ERRORS in $f:"; $errs | ForEach-Object { Write-Host "  $_" } }
	else { Write-Host "PARSE OK: $f" }
}
if (-not $ok) { exit 1 }
Import-Module PSScriptAnalyzer -ErrorAction SilentlyContinue
if (Get-Module PSScriptAnalyzer) {
	$r = Invoke-ScriptAnalyzer -Path ./api/_lib/pantry-store.ps1 -Severity Warning,Error
	if ($r) { $r | Format-Table -AutoSize | Out-String | Write-Host } else { Write-Host "PSScriptAnalyzer: clean (no warnings/errors) on pantry-store.ps1" }
} else { Write-Host "PSScriptAnalyzer not installed; skipped" }
' 2>&1

